UPDATE factory_settlement_payment p JOIN (SELECT settlement_batch_id,SUM(actual_unlock_amount_fen) paid,MIN(sharing_status='success') done,MAX(sharing_status='failed') failed FROM wechat_profit_sharing_order WHERE settlement_batch_id=#{id} GROUP BY settlement_batch_id) w ON w.settlement_batch_id=p.settlement_batch_id
    SET p.actual_paid_amount_fen=w.paid,p.payment_status=IF(w.done AND w.paid=p.payable_amount_fen,'success',IF(w.failed,'failed','processing')),p.paid_at=IF(w.done AND w.paid=p.payable_amount_fen,#{at},NULL),p.updated_at=#{at}
    WHERE p.settlement_batch_id=#{id} AND p.payment_status IN ('processing','failed')

UPDATE custom_order_settlement d JOIN wechat_profit_sharing_order w ON w.custom_settlement_id=d.id JOIN platform_commission_record c ON c.custom_settlement_id=d.id
    SET d.settlement_status=IF(w.sharing_status='success','settled',d.settlement_status),d.updated_at=#{at},c.commission_status=IF(w.commission_status IN ('success','not_required'),'confirmed',c.commission_status),c.updated_at=#{at}
    WHERE d.settlement_batch_id=#{id}
